mapper.select:
select resource_management.*,dept.name as dept_name,dept.id as dept_id
,ouser.username authorizedObjectName,ouser.name authorizedObjectNameCn
,muser.username as modifyUserName,muser.name as modifyUserNameCn
,euser.username as authorizeUserName,euser.name as authorizeNameCn

from resource_management
left join user ouser on resource_management.authorized_object_id=ouser.id
left join user muser on resource_management.modify_user_id= muser.id
left join user euser on resource_management.authorize_user_id= euser.id
left join dept on ouser.dept_id= dept.id

    resource_management.authorized_object_type=1

        and resource_management.resource_type in

            #{item}



        and resource_management.object_name like concat('%',#{param.keywords},'%')


        and resource_management.application_code=#{param.applicationCode}


        and resource_management.authorized_object_id in

            #{item}



        and dept.id in

            #{item}



        and resource_management.auth_download in

            #{item}



        and resource_management.authorize_user_id in

            #{item}



        and resource_management.auth_time BETWEEN #{param.authTimeBegin} and  #{param.authTimeEnd}


        and resource_management.modify_time BETWEEN  #{param.modifyTimeBegin} and #{param.modifyTimeEnd}



        and resource_management.modify_user_id in

            #{item}



        and resource_management.online_status =#{param.onlineStatus}

select resource_management.*,
ouser.username authorizedObjectName
from resource_management
left join user ouser on resource_management.authorized_object_id=ouser.id

    resource_management.online_status =1

        and resource_management.object_id =#{param.objectId}


        and resource_management.resource_type =#{param.resourceType}


        and resource_management.application_code=#{param.applicationCode}


        and resource_management.authorized_object_id= #{param.authorizedUserId}


        and resource_management.authorized_object_type= #{param.authorizedObjectType}









        and resource_management.auth_download in

            #{item}

select resource_management.*
,ogroup.group_name authorizedUserGroupName
,muser.username as modifyUserName,muser.name as modifyUserNameCn
,euser.username as authorizeUserName,euser.name as authorizeNameCn

from resource_management
left join `group` ogroup on resource_management.authorized_object_id=ogroup.id
left join user muser on resource_management.modify_user_id= muser.id
left join user euser on resource_management.authorize_user_id= euser.id

    resource_management.authorized_object_type=2

        and resource_management.resource_type in

            #{item}



        and resource_management.object_name like concat('%',#{param.keywords},'%')


        and resource_management.application_code=#{param.applicationCode}


        and resource_management.authorized_object_id in

            #{item}



        and resource_management.auth_download in

            #{item}



        and resource_management.authorize_user_id in

            #{item}



        and resource_management.auth_time BETWEEN #{param.authTimeBegin} and  #{param.authTimeEnd}


        and resource_management.modify_time BETWEEN  #{param.modifyTimeBegin} and #{param.modifyTimeEnd}



        and resource_management.modify_user_id in

            #{item}



        and resource_management.online_status =#{param.onlineStatus}

SELECT rs.*
FROM resource_management rs
         LEFT JOIN user ouser ON rs.authorized_object_id = ouser.id
    AND rs.authorized_object_type = 1
         LEFT JOIN (
    SELECT g.id as group_id
    FROM `group` g
             INNER JOIN groups_users gu ON g.id = gu.group_id
    WHERE gu.user_id = #{userId}
) g2 ON rs.authorized_object_id = g2.group_id
    AND rs.authorized_object_type = 2
WHERE rs.online_status = 1
  AND rs.resource_type = #{resourceType}
  AND rs.application_code = #{applicationCode}
  AND (
        (rs.authorized_object_type = 1 AND ouser.id = #{userId}) OR
        (rs.authorized_object_type = 2 AND g2.group_id IS NOT NULL)
    )

      and rs.object_id in

          #{item}
